var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

var threshold = flow.get('threshold');
if (threshold === undefined || threshold === null) {
    threshold = 30.0;
    flow.set('threshold', threshold);
}

var isAlert = Number(data.suhu) > Number(threshold);
var alertMsg = isAlert 
    ? `PERINGATAN: Suhu ${data.suhu}°C melewati batas maksimal ${threshold}°C!`
    : null;

var suhu = Number(data.suhu);
var kelembaban = Number(data.kelembaban);
var ts = String(data.timestamp || '').replace(/'/g, "''");
var rec = String(data.received || '').replace(/'/g, "''");
var sqlMsg = {
    topic: `INSERT INTO sensor_history (suhu, kelembaban, timestamp, received) VALUES (${suhu}, ${kelembaban}, '${ts}', '${rec}');`
};

var wsMsg = {
    payload: JSON.stringify({
        type: 'sensor_update',
        data: data,
        threshold: threshold,
        alert: isAlert,
        alert_message: alertMsg
    })
};

var mqttAlertMsg = null;
if (isAlert) {
    mqttAlertMsg = {
        topic: 'iot/alert',
        payload: {
            alert: true,
            suhu: suhu,
            threshold: threshold,
            message: alertMsg,
            timestamp: data.received
        }
    };
}

return [sqlMsg, wsMsg, mqttAlertMsg, { payload: data }];

const VALID_KEY = 'iot-secret-key-2026';
if (msg.req.headers['x-api-key'] !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [null, msg];
}
return [msg, null];

var data = flow.get('lastSensor') || { suhu: null, kelembaban: null, timestamp: null };
var threshold = flow.get('threshold') || 30.0;
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    threshold: threshold,
    data: data,
    server_time: new Date().toISOString()
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

const VALID_KEY = 'iot-secret-key-2026';
if (msg.req.headers['x-api-key'] !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [null, msg];
}
msg.topic = 'SELECT suhu, kelembaban, timestamp, received FROM sensor_history ORDER BY id DESC LIMIT 50;';
return [msg, null];

var rows = (msg.payload || []).reverse();
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    count: rows.length,
    data: rows
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

const VALID_KEY = 'iot-secret-key-2026';
if (msg.req.headers['x-api-key'] !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [null, msg];
}
return [msg, null];

var body = msg.payload;
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'device dan action wajib diisi' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [msg, null];
}

var mqttMsg = { payload: body, topic: 'iot/kontrol' };

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return [msg, mqttMsg];

const VALID_KEY = 'iot-secret-key-2026';
if (msg.req.headers['x-api-key'] !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [null, msg];
}
return [msg, null];

var val = Number(msg.payload.threshold);
if (isNaN(val)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Nilai threshold harus berupa angka' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [msg, null];
}

flow.set('threshold', val);

var wsMsg = {
    payload: JSON.stringify({
        type: 'threshold_update',
        threshold: val
    })
};

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: `Batas suhu berhasil diatur ke ${val}°C`,
    threshold: val
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return [msg, wsMsg];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
